const MT_UP={cost:60000,mats:{soul:6,crest:1},chance:0.12};
function doUpMount(p,id){ if(!p.mounts||!p.mounts.includes('wolf')){ sendTo(id,{t:'toast',text:'Cần có Sói Xám Thảo Nguyên.'}); return; }
  if((p.lv||1)<100){ sendTo(id,{t:'toast',text:'Cần cấp 100.'}); return; }
  if(p.gold<MT_UP.cost){ sendTo(id,{t:'toast',text:'Không đủ vàng.'}); return; }
  p.mats=p.mats||{}; for(const k in MT_UP.mats) if((p.mats[k]||0)<MT_UP.mats[k]){ sendTo(id,{t:'toast',text:'Thiếu '+MATS[k]+' ('+(p.mats[k]||0)+'/'+MT_UP.mats[k]+')'}); return; }
  p.gold-=MT_UP.cost; for(const k in MT_UP.mats) p.mats[k]-=MT_UP.mats[k];
  const _ch=p._tame?0.40:MT_UP.chance; p._tame=0;
  if(Math.random()<_ch){ const pool=['frostwolf','shadowwolf','direwolf'].filter(x=>!p.mounts.includes(x)); const got=(pool.length?pool:['frostwolf','shadowwolf','direwolf'])[Math.floor(Math.random()*(pool.length||3))];
    if(p.mounted==='wolf') doToggleMount(p,id,'wolf'); p.mounts=p.mounts.filter(x=>x!=='wolf'); if(!p.mounts.includes(got)) p.mounts.push(got);
    const mt=MOUNTS.find(x=>x.id===got); bcast({t:'toast',text:'🐺 '+(p.charDisplayName||'Ai đó')+' đã thuần hóa '+mt.name+'!'}); sendTo(id,{t:'mtup',ok:1,id:got}); }
  else sendTo(id,{t:'mtup',ok:0});
  sendTo(id,{t:'mounts',owned:p.mounts,mounted:p.mounted}); sendInv(p,id); sendShopData(p,id); }
function sellValue(it){ return Math.max(2, Math.round(((it.tier||1)*15 + (it.plus||0)*8)*[1,2,5,12][it.rar|0])); }
