function wpnType(p){ const w=p.equip&&p.equip.wpn; if(!w)return null; const L=ITEM_LOOKS.wpn.find(x=>x.id===w.look); return L&&L.r?L.r.w:null; }
function raceAff(p){ const R=RACES[p.race]; if(!R)return 1; const w=wpnType(p); return (w&&R.aff.includes(w))?(1.08+Math.min(0.17,(p.lv||1)*0.0012)):1; }
function cleanMounts(p){ if(p.mounts) p.mounts=p.mounts.filter(m=>MOUNTS.some(x=>x.id===m)); if(p.mounted&&!MOUNTS.some(x=>x.id===p.mounted)) p.mounted=null; }
function moveMul(p){ return 0.62*((p.equip&&p.equip.wing&&!p.mounted)?1.12:1); }
function mountSpdMul(p){ const rs=1+((RACES[p.race]||{}).spd||0); if(!p.mounted)return rs; const mt=MOUNTS.find(x=>x.id===p.mounted); return (mt?mt.spdMul:1)*rs; }
