function npcProgress(p,def){
  if(def.checkKey==='plus3'){
    for(const s of SLOTS){ if(p.equip[s]&&(p.equip[s].plus||0)>=3)return 1; }
    for(const it of (p.inv||[])){ if((it.plus||0)>=3)return 1; }
    return 0;
  }
  const cum=(p.cum&&p.cum[def.checkKey])||0;
  const snap=p.npcAccepted?p.npcAccepted[def.id]:undefined;
  if(snap===undefined)return 0;
  return Math.max(0,cum-snap);
}
function npcQuestState(p,npcId,idx,def){
  if(p.npcClaimed&&p.npcClaimed[def.id])return 'claimed';
  const chain=NPC_QUESTS[npcId];
  if(idx>0 && !(p.npcClaimed&&p.npcClaimed[chain[idx-1].id]))return 'locked';
  const accepted=p.npcAccepted&&(def.checkKey==='plus3'?p.npcAccepted[def.id]!==undefined:p.npcAccepted[def.id]!==undefined);
  if(!accepted)return 'available';
  return npcProgress(p,def)>=def.target?'claimable':'accepted';
}
function sendNpcData(p,id,npcId){
  const npc=NPCS.find(n=>n.id===npcId); if(!npc)return;
  const chain=NPC_QUESTS[npcId]||[];
  const quests=chain.map((def,idx)=>({id:def.id,name:def.name,desc:def.desc,target:def.target,progress:npcProgress(p,def),reward:def.reward,state:npcQuestState(p,npcId,idx,def)}));
  sendTo(id,{t:'npcdata',npcId,name:npc.name,icon:npc.icon,greet:npc.greet,quests});
}
function doAcceptNpcQ(p,id,npcId,qid){
  const chain=NPC_QUESTS[npcId]; if(!chain)return; const idx=chain.findIndex(q=>q.id===qid); if(idx<0)return; const def=chain[idx];
  if(npcQuestState(p,npcId,idx,def)!=='available')return;
  if(!p.npcAccepted)p.npcAccepted={};
  p.npcAccepted[qid]= def.checkKey==='plus3' ? 1 : ((p.cum&&p.cum[def.checkKey])||0);
  sendNpcData(p,id,npcId);
}
function doClaimNpcQ(p,id,npcId,qid){
  const chain=NPC_QUESTS[npcId]; if(!chain)return; const idx=chain.findIndex(q=>q.id===qid); if(idx<0)return; const def=chain[idx];
  if(npcQuestState(p,npcId,idx,def)!=='claimable')return;
  if(!p.npcClaimed)p.npcClaimed={}; p.npcClaimed[qid]=true;
  const r=def.reward;
  if(r.gold)p.gold+=r.gold; if(r.stones)p.stones=(p.stones||0)+r.stones; if(r.xp)gainXP(p,r.xp);
  if(r.itemTier){ const item=makeItem(r.itemTier); applyLine(item,ztier(p.zone)||1,p); if(p.inv.length<24)p.inv.push(item); }
  bcast({t:'gold',id,x:p.x,y:p.y,val:r.gold||0,st:r.stones||0});
  sendNpcData(p,id,npcId); sendInv(p,id);
}
function sendShopData(p,id){
  sendTo(id,{t:'shopdata',potions:POTIONS.filter(x=>x.tw===p.zone||(x.tw==='*'&&ZONES[p.zone]&&ZONES[p.zone].safe)),zone:p.zone,gold:p.gold,
    inv:(p.inv||[]).map(it=>({id:it.id,slot:it.slot,tier:it.tier,plus:it.plus||0,sell:sellValue(it)}))});
}
function lootNm(it){ ensureLook(it); return lookName(it)+((it.plus||0)>0?(' +'+it.plus):''); }
function lootSc(it){ if(!it.set)return 0; const g=GSETS.find(x=>x.id===it.set); return g?g.col:0; }
function potCat(){ return POTIONS.filter(x=>!x.reset).map(x=>({id:x.id,n:x.name.replace(/^\S+\s/,''),ico:x.ico,hp:x.hp||0,mp:x.mp||0,b:x.buff||0})); }
function sendPots(p,id,cat){ if(!p.pots)p.pots={hp:5,mp:5}; const now=Date.now(); sendTo(id,{t:'pots',pots:p.pots,bA:Math.max(0,(p.elxA||0)-now),bD:Math.max(0,(p.elxD||0)-now),cat:cat?potCat():undefined}); }
function doUsePot(p,id,k){ if(!p||p.dead||!p.pots||!(p.pots[k]>0))return; const pot=POTIONS.find(x=>x.id===k); if(!pot||pot.reset)return;
  const now=Date.now(), grp=pot.hp?'h':(pot.mp?'m':'b'+pot.buff); p._potT=p._potT||{}; if((p._potT[grp]||0)>now)return; p._potT[grp]=now+(grp.charAt(0)==='b'?1000:1200);
  if(pot.hp){ if(p.hp>=p.maxhp)return; p.hp=Math.min(p.maxhp,p.hp+pot.hp); hitEv(p.x,p.y-20,pot.hp,true); }
  if(pot.mp){ if(p.mp>=p.maxmp)return; p.mp=Math.min(p.maxmp,p.mp+pot.mp); }
  if(pot.buff==='A') p.elxA=now+60000; if(pot.buff==='D') p.elxD=now+60000;
  p.pots[k]--; if(p.pots[k]<=0) delete p.pots[k]; sendPots(p,id); }
function doPickLoot(p,id,lid){ if(!p||p.dead)return; let best=-1, bd=1e9;
  for(let i=0;i<loot.length;i++){ const it=loot[i]; if(it.zone!==p.zone)continue; if(lid!=null&&it.item.id!==lid)continue; if(lid==null&&it.noPick!=null&&it.noPick==id)continue;
    const d=Math.hypot(p.x-it.x,p.y-it.y); if(d<bd){ bd=d; best=i; } }
  if(best<0||(lid==null&&bd>220)){ if(lid==null&&typeof doGather==='function'&&doGather(p,id,null)) return; }
  if(best<0)return; if(bd>(lid!=null?190:220)){ sendTo(id,{t:'toast',text:'Quá xa'}); return; }
  const it=loot[best]; loot.splice(best,1); pickup(p,id,it); }
function doBuyPotion(p,id,kind,qty,internal){
  const pot=POTIONS.find(x=>x.id===kind); if(!pot||(pot.tw!=='kc'&&pot.tw!==p.zone&&!(pot.tw==='*'&&ZONES[p.zone]&&ZONES[p.zone].safe)))return; if(pot.tw==='kc'&&!internal) return;
  const n=(!pot.reset&&qty===10)?10:1; if(p.gold<pot.cost*n)return;
  p.gold-=pot.cost*n;
  if(!pot.reset){ if(!p.pots)p.pots={}; p.pots[kind]=Math.min(999,(p.pots[kind]||0)+n); sendPots(p,id); }
  if(pot.reset==='stat'){ let back=0; for(const k of ['STR','AGI','VIT','INT']){ const o=Math.max(0,ownStat(p,k)); back+=o; p[k]=(p[k]||0)-o; } p.statPts=(p.statPts||0)+back; recompute(p);
    for(const sl of SLOTS){ const it=p.equip[sl]; if(it&&canWear(p,it)&&p.inv.length<24){ p.inv.push(it); p.equip[sl]=null; } } recompute(p); sendTo(id,{t:'toast',text:'Điểm chỉ số đã được hoàn lại.'}); }
  if(pot.reset==='skill'){ p.skRank={}; p.skBr=null; for(const k in (p.loadout||{})){ const sk=findSkill(p.cls,p.loadout[k]); if(sk&&!meetsReq(p,sk)) p.loadout[k]=null; } p.skillPts=skBudget(p.lv); recompute(p); sendTo(id,{t:'toast',text:'Điểm kỹ năng đã được hoàn lại.'}); }
  if(pot.reset){ sendTo(id,{t:'skills',meta:skillMeta(p),passive:PASSIVES[p.cls],full:fullSkillList(p),tree:treeInfo(p),loadout:p.loadout}); sendInv(p,id); }
  if(!internal) sendShopData(p,id);
}
function doBuyMount(p,id,mountId){
  const mt=MOUNTS.find(x=>x.id===mountId); if(!mt||mt.up||mt.old)return;
  if(mt.tw&&p.zone!==mt.tw){ sendTo(id,{t:'toast',text:mt.name+' chỉ bán ở '+(ZONES[mt.tw]?ZONES[mt.tw].name:mt.tw)}); return; }
  if(!p.mounts)p.mounts=[]; if(p.mounts.includes(mountId))return;
  if((p.lv||1)<(mt.lv||1)){ sendTo(id,{t:'toast',text:'Cần cấp '+mt.lv+' để cưỡi '+mt.name}); return; }
  if(p.gold<mt.cost){ sendTo(id,{t:'toast',text:'Không đủ vàng mua '+mt.name}); return; }
  p.gold-=mt.cost; p.mounts.push(mountId);
  sendTo(id,{t:'toast',text:'🎉 Đã mua '+mt.name+'!'}); sendShopData(p,id); sendTo(id,{t:'mounts',owned:p.mounts,mounted:p.mounted});
}
function doToggleMount(p,id,mountId){
  const cur=p.mounted?MOUNTS.find(x=>x.id===p.mounted):null;
  if(p.mounted===mountId){
    if(cur&&cur.allStat){ p.STR-=cur.allStat;p.VIT-=cur.allStat;p.AGI-=cur.allStat;p.INT-=cur.allStat; }
    p.mounted=null;
  } else if(p.mounts && p.mounts.includes(mountId)){
    if(cur&&cur.allStat){ p.STR-=cur.allStat;p.VIT-=cur.allStat;p.AGI-=cur.allStat;p.INT-=cur.allStat; }
    const mt=MOUNTS.find(x=>x.id===mountId);
    if(mt&&mt.allStat){ p.STR+=mt.allStat;p.VIT+=mt.allStat;p.AGI+=mt.allStat;p.INT+=mt.allStat; }
    p.mounted=mountId;
  } else return;
  recompute(p);
  sendTo(id,{t:'mounts',owned:p.mounts,mounted:p.mounted});
  sendTo(id,{t:'skills',meta:skillMeta(p),passive:PASSIVES[p.cls],full:fullSkillList(p),tree:treeInfo(p),loadout:p.loadout}); sendInv(p,id);
}
function doSellItem(p,id,itemId){
  const idx=(p.inv||[]).findIndex(x=>x.id===itemId); if(idx<0)return;
  const it=p.inv[idx]; p.inv.splice(idx,1); p.gold+=sellValue(it);
  sendInv(p,id); sendShopData(p,id);
}
