const SUB_LV1=60, SUB_LV2=120, WPN_KIND={1:'sword',2:'axe',3:'staff',4:'xbow',5:'spear',6:'sword',7:'staff',8:'axe',9:'sword',20:'axe',21:'spear',22:'staff',23:'staff',24:'xbow',25:'spear',26:'sword',27:'sword',28:'spear',29:'staff'};
function subOf(p){ const L=SUBCLASS[p.cls]||[]; return L.find(x=>x.id===p.sub)||null; }
function branchAff(p){ const L=SUBCLASS[p.cls]; if(!L)return null; const sc=L.map(S=>{ let v=0; for(const k in S.st) v+=(p[k]||0)*S.st[k]*0.5; for(const sid of S.sk){ const pr=PASMAP[sid]?((p.skRank&&p.skRank[sid])||0)*10:Math.max(0,((p.skRank&&p.skRank[sid])||1)-1)*6; v+=pr; } return v+1; });
  const tot=sc.reduce((a,b)=>a+b,0); const sh=sc.map(v=>v/tot); let lean=0; sh.forEach((v,i)=>{ if(v>sh[lean]) lean=i; }); return {pa:sh[0], sh, lean, dom:sh[lean]}; }
function subB(p,k){ const S=subOf(p); if(!S)return 0; return (S.b[k]||0)*(p.subT>=2?1.6:1)*(p.subPow||1); }
function evalBranch(p,id){ if(!p.chosen)return; const A=branchAff(p); if(!A)return; const L=SUBCLASS[p.cls]; const lv=p.lv||1; p.subAff=A.pa;
  let ev=null;
  if(lv<SUB_LV1){ if(p.sub){ p.sub=null; p.subT=0; } }
  else if(!p.sub){ if(A.dom>=0.45){ p.sub=L[A.lean].id; p.subT=(lv>=SUB_LV2&&A.dom>=0.52)?2:1; ev='awaken'; } }
  else { const cur=L.findIndex(x=>x.id===p.sub); if(cur!==A.lean&&A.dom>=0.52){ p.sub=L[A.lean].id; ev='shift'; }
    if((p.subT||1)<2&&lv>=SUB_LV2&&A.dom>=0.52&&L[A.lean].id===p.sub){ p.subT=2; ev='ascend'; } }
  const pow=Math.max(0.5,Math.min(1,(A.dom-0.34)*3.2)); if(Math.abs((p.subPow||0)-pow)>0.02){ p.subPow=pow; recompute(p); }
  if(ev){ recompute(p); sendInv(p,id); } }
function sendSub(p,id){ const A=branchAff(p)||{pa:0.5,sh:[0.34,0.33,0.33]}; sendTo(id,{t:'subdata',list:(SUBCLASS[p.cls]||[]).map(S=>({id:S.id,name:S.name,t2:S.t2,col:S.col,desc:S.desc,wk:S.wk})),sub:p.sub||null,subT:p.subT||0,lv1:SUB_LV1,lv2:SUB_LV2,pa:A.pa,sh:A.sh,pow:p.subPow||0}); }
