    if(d.k==='scorch'){ var gr=ctx.createRadialGradient(d.x,d.y,1,d.x,d.y,d.R); gr.addColorStop(0,'rgba(10,6,4,0.85)'); gr.addColorStop(0.6,'rgba(30,14,8,0.5)'); gr.addColorStop(1,'rgba(0,0,0,0)'); ctx.fillStyle=gr; ctx.beginPath(); ctx.ellipse(d.x,d.y,d.R,d.R*0.55,0,0,7); ctx.fill();
      if(age<d.life*0.5){ ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=a*0.5*(1-age/(d.life*0.5)); ctx.fillStyle=d.c||'#ff6a1a'; for(var k=0;k<6;k++){ var aa=d.seed+k*1.1, rr=d.R*(0.2+0.6*((k*37+d.seed)%10)/10); ctx.fillRect(Math.round(d.x+Math.cos(aa)*rr),Math.round(d.y+Math.sin(aa)*rr*0.55),2,2); } } }
