var BLOOD=[];
function addBlood(x,y,r){ var n=5+Math.floor(Math.random()*5), sp=[]; for(var i=0;i<n;i++) sp.push([ (Math.random()-0.5)*r*2.4,(Math.random()-0.3)*r*1.0,2+Math.random()*r*0.55 ]); BLOOD.push({x:x,y:y+r*0.5,z:myZone,t:performance.now(),sp:sp}); if(BLOOD.length>60)BLOOD.shift(); }
function drawBlood(){ var now=performance.now(); for(var i=BLOOD.length-1;i>=0;i--){ var b=BLOOD[i]; var age=(now-b.t)/1000; if(age>35){ BLOOD.splice(i,1); continue; } if(b.z!==myZone)continue;
    var a=Math.min(1,age*4)*Math.max(0,1-Math.max(0,age-20)/15); ctx.save(); ctx.globalAlpha=0.72*a;
    for(var k=0;k<b.sp.length;k++){ var q=b.sp[k]; ctx.fillStyle=k%3?'#5a0a0a':'#7a1010'; ctx.beginPath(); ctx.ellipse(b.x+q[0],b.y+q[1],q[2]*1.4,q[2]*0.7,0,0,7); ctx.fill(); }
    ctx.globalAlpha=0.5*a; ctx.fillStyle='#2a0404'; ctx.beginPath(); ctx.ellipse(b.x,b.y,b.sp[0][2]*2.2,b.sp[0][2]*0.9,0,0,7); ctx.fill(); ctx.restore(); } }
function drawHumMob(k,cx,cy,size,dir,moving,atk,deadT){ var im=monImg(k), M=MONM[k]; if(!im||!M)return 0; var t=performance.now(), row, col, cw=M[0], ch=M[1];
  if(deadT){ row=8; col=Math.min(M[4]-1,Math.floor((t-deadT)/110)); }
  else if(atk==='ca'&&M[6]){ row=9+dir; col=Math.floor(t/95)%M[6]; }
  else if(atk){ row=4+dir; col=Math.floor(t/85)%M[3]; }
  else { row=dir; col=moving?(M[2]===9?1+Math.floor(t/80)%8:Math.floor(t/110)%M[2]):0; }
  size*=(HUMSZ[k]||1); var s=size/64, w=cw*s, h=ch*s, pd=(M[5]||0)*s; ctx.imageSmoothingEnabled=false; ctx.drawImage(im,col*cw,row*ch,cw,ch,Math.round(cx-w/2),Math.round(cy-h+pd),Math.round(w),Math.round(h)); return (h-pd)*0.82; }
