var SLOTS=[], SLSEL=-1, SLTIMER=null;
function slotName(c){ var n=(CLS[c]&&CLS[c].n)||c; return n.split(' ').slice(1).join(' '); }
function renderSlots(slots){ SLOTS=slots||[]; var box=document.getElementById('slotCards'); box.innerHTML='';
  if(SLSEL<0||!SLOTS[SLSEL]){ SLSEL=SLOTS.findIndex(function(x){return !!x;}); }
  for(var i=0;i<5;i++){(function(idx){ var s=SLOTS[idx]; var el=document.createElement('div'); el.className='chsl'+(s?'':' empty')+(idx===SLSEL?' chon':'');
    el.innerHTML=s?('<div class="chtag"><b>'+(s.name||'???').replace(/</g,'')+'</b><span>'+slotName(s.cls)+'</span><i>Lv '+s.lv+'</i></div><canvas width="64" height="64"></canvas><div class="chped"></div>')
                  :('<div class="chtag dim"><b>Ô trống</b><span>&nbsp;</span><i>&nbsp;</i></div><div class="chghost"></div><div class="chped"></div>');
    el.addEventListener('pointerdown',function(ev){ev.preventDefault(); SLSEL=idx; renderSlots(SLOTS); if(!s) slotAct('new'); });
    box.appendChild(el); })(i); }
  document.getElementById('slDel').disabled=!(SLOTS[SLSEL]); document.getElementById('slGo').disabled=!(SLOTS[SLSEL]);
  document.getElementById('slNew').disabled=SLOTS.filter(function(x){return !x;}).length===0;
  if(!SLTIMER) SLTIMER=setInterval(drawSlotDolls,110); drawSlotDolls(); }
function drawSlotDolls(){ var scr=document.getElementById('slotScr'); if(!scr||scr.style.display==='none'){ clearInterval(SLTIMER); SLTIMER=null; return; }
  var cvs=document.querySelectorAll('#slotCards .chsl'); var t=performance.now();
  for(var i=0;i<cvs.length;i++){ var s=SLOTS[i], cv=cvs[i].querySelector('canvas'); if(!s||!cv)continue; var sel=(i===SLSEL);
    var col=sel?(1+Math.floor(t/110)%8):0; try{ composeDoll(s.g||'m',s.eq||{},2,col,sel,cv,null,s.cls,s.rc||'human'); }catch(e){} } }
function slotAct(a){ var msg=document.getElementById('slotMsg'); msg.textContent='';
  if(a==='go'){ if(SLOTS[SLSEL]&&ws.readyState===1) ws.send(JSON.stringify({t:'selectslot',slot:SLSEL+1})); }
  else if(a==='new'){ var idx=(SLSEL>=0&&!SLOTS[SLSEL])?SLSEL:SLOTS.findIndex(function(x){return !x;}); if(idx<0){ msg.textContent='Đã đủ 5 nhân vật.'; return; } SLSEL=idx; if(ws.readyState===1) ws.send(JSON.stringify({t:'selectslot',slot:idx+1})); }
  else if(a==='del'){ var s=SLOTS[SLSEL]; if(!s)return; gPrompt('Xóa vĩnh viễn "'+s.name+'"? Gõ đúng tên nhân vật để xác nhận:','',function(nm){ if(ws.readyState===1) ws.send(JSON.stringify({t:'delslot',slot:SLSEL+1,confirm:nm})); }); } }
