var GP=[];
function gpPos(id){ var p=players[id]; if(!p) return null; return {x:(p._rx!=null?p._rx:p.x),y:(p._ry!=null?p._ry:p.y)}; }
function geTgt(m){ if(m.te!=null){ var e=enemies[m.te]; if(e&&!e.dead) return {x:e.x,y:e.y,r:e.r||14}; return null; } if(m.tp!=null){ var q=gpPos(m.tp); if(q){ q.r=14; return q; } } return null; }
