function gLine(x0,y0,x1,y1,col,w,a){ ctx.save(); ctx.globalAlpha=a==null?1:a; ctx.strokeStyle=col; ctx.lineWidth=w; ctx.lineCap='round'; ctx.shadowColor=col; ctx.shadowBlur=10; ctx.beginPath(); ctx.moveTo(x0,y0); ctx.lineTo(x1,y1); ctx.stroke(); ctx.restore(); }
function gJag(pts,col,w,a){ ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=a; ctx.strokeStyle=col; ctx.lineWidth=w; ctx.shadowColor=col; ctx.shadowBlur=14; ctx.beginPath();
  for(var i=0;i<pts.length-1;i++){ var A=pts[i], B=pts[i+1], n=6; ctx.moveTo(A[0],A[1]); for(var k=1;k<=n;k++){ var u=k/n, j=(k<n)?(Math.random()-0.5)*18:0; ctx.lineTo(A[0]+(B[0]-A[0])*u+j,A[1]+(B[1]-A[1])*u+j*0.6); } }
  ctx.stroke(); ctx.lineWidth=Math.max(1,w*0.35); ctx.strokeStyle='#ffffff'; ctx.stroke(); ctx.restore(); }
function gChain(x0,y0,x1,y1,tint){ var d=Math.hypot(x1-x0,y1-y0), a=Math.atan2(y1-y0,x1-x0), n=Math.max(1,Math.floor(d/18)); for(var i=0;i<n;i++){ var u=(i+0.5)/n; fxDraw('chain',0,x0+(x1-x0)*u,y0+(y1-y0)*u,0.55,{rot:a,tint:tint}); } }
function gArrowFan(x,y,a,R,arc,n,col,dur){ for(var i=0;i<n;i++){ var aa=a+(n>1?(i/(n-1)-0.5)*2*arc:0)+(Math.random()-0.5)*0.05, r=R*(0.8+Math.random()*0.2); afx({n:'bigarrow',x:x,y:y-14,vx:Math.cos(aa)*r,vy:Math.sin(aa)*r*0.62,rot:Math.atan2(Math.sin(aa)*0.62,Math.cos(aa)),sc:0.32,tint:col,add:1,dur:dur||0.22,delay:i*0.015}); } }
