var CHC={world:'#e8dcc0',guild:'#8fff9a',party:'#7ad0ff',whisper:'#ff9ae8',sys:'#ffd76b'}, CHN={world:'Thế giới',guild:'Hội',party:'Tổ đội',whisper:'Riêng',sys:'Hệ thống'};
function chatPush(m){ var who=m.n||((players[m.id]&&players[m.id].name)||('#'+m.id)); CHAT.all.push({c:m.channel||'world',who:who,tx:m.text,t:performance.now()}); if(CHAT.all.length>120) CHAT.all.shift(); if(!CHAT.open&&m.id!=myId) CHAT.unread++; renderChatHud(); }
function chatSys(tx){ CHAT.all.push({c:'sys',who:'',tx:tx,t:performance.now()}); if(CHAT.all.length>120) CHAT.all.shift(); renderChatHud(); }
function renderChatHud(){ var h=document.getElementById('chatHud'); if(!h) return; var L=CHAT.all.filter(function(x){ return CHAT.tab==='all'||x.c===CHAT.tab; }); var now=performance.now();
  if(!CHAT.open) L=L.filter(function(x){ return now-x.t<14000; }).slice(-4); else L=L.slice(-60);
  var log=document.getElementById('chLog'); log.innerHTML=L.map(function(x){ return '<div class="chl"><span class="chc" style="color:'+CHC[x.c]+'">['+CHN[x.c]+']</span> '+(x.who?'<b>'+escapeHtml(x.who)+':</b> ':'')+escapeHtml(x.tx)+'</div>'; }).join('');
  log.scrollTop=log.scrollHeight; h.classList.toggle('open',CHAT.open); h.classList.toggle('empty',!CHAT.open&&!L.length);
  var bd=document.getElementById('chBadge'); if(bd){ bd.textContent=CHAT.unread>9?'9+':CHAT.unread; bd.style.display=(!CHAT.open&&CHAT.unread)?'':'none'; }
  document.querySelectorAll('#chTabs button').forEach(function(b){ b.classList.toggle('on',b.getAttribute('data-t')===CHAT.tab); });
  document.querySelectorAll('#chCh button').forEach(function(b){ b.classList.toggle('on',b.getAttribute('data-c')===CHAT.ch); }); }
function chatSend(){ var el=document.getElementById('chIn'), t=(el.value||'').trim(); if(!t) return; var c=CHAT.ch;
  if(t.charAt(0)==='@'||t.charAt(0)==='/') c='world';
  if(c==='guild') ws.send(JSON.stringify({t:'guildchat',text:t})); else if(c==='party') ws.send(JSON.stringify({t:'pchat',text:t})); else ws.send(JSON.stringify({t:'chat',text:t})); el.value=''; }
setInterval(function(){ if(!CHAT.open) renderChatHud(); },3000);
// ---- HỘP THƯ ----
var MAIL={list:[],sel:null,tab:'in',n:0};
function renderMail(){ var b=document.getElementById('mailBody'); if(!b) return; var h='<div class="tabs"><button class="tabbtn'+(MAIL.tab==='in'?' on':'')+'" data-mt="in">📥 Hộp thư ('+MAIL.list.length+')</button><button class="tabbtn'+(MAIL.tab==='new'?' on':'')+'" data-mt="new">✍ Viết thư</button></div>';
  if(MAIL.tab==='in'){ if(!MAIL.list.length) h+='<div class="pd" style="margin:14px 0">Chưa có thư nào.</div>';
    MAIL.list.forEach(function(m){ var sel=MAIL.sel===m.id; h+='<div class="mrow'+(m.r?'':' unr')+(sel?' sel':'')+'" data-id="'+m.id+'"><span class="mic">'+(m.att&&!m.c?'🎁':(m.sys?'⚜':'✉'))+'</span><div style="flex:1;min-width:0"><div class="mti">'+escapeHtml(m.ti)+'</div><div class="mfr">'+escapeHtml(m.f||'')+' · '+(m.at?new Date(m.at).toLocaleDateString('vi-VN'):'')+'</div></div></div>';
      if(sel){ h+='<div class="mbody">'+escapeHtml(m.b||'').split(String.fromCharCode(10)).join('<br>')+(m.att?'<div class="matt">🎁 Quà: '+mailAttTxt(m.att)+'</div>':'')+'<div class="mbtns">'+(m.att&&!m.c?'<button class="gbtn" data-claim="'+m.id+'">Nhận quà</button>':'')+(!m.sys&&m.f?'<button class="gbtn" data-rep="'+escapeHtml(m.f)+'">Trả lời</button>':'')+'<button class="gbtn" data-del="'+m.id+'">Xóa</button></div></div>'; } }); }
  else { h+='<div class="mform"><input id="mTo" maxlength="16" placeholder="Gửi cho (tên nhân vật)" value="'+escapeHtml(MAIL.to||'')+'"><input id="mTi" maxlength="40" placeholder="Tiêu đề"><textarea id="mBo" maxlength="400" placeholder="Nội dung (tối đa 400 chữ)"></textarea>';
    if(ADM.on) h+='<div class="madm">⚜ Quản trị: <label><input type="checkbox" id="mAll"> gửi TẤT CẢ nhân vật</label> · quà: <input id="mGold" type="number" placeholder="vàng" style="width:70px"> <input id="mChaos" type="number" placeholder="Tinh Thể" style="width:60px"> <input id="mBless" type="number" placeholder="Huyết Ấn" style="width:60px"> <input id="mSoul" type="number" placeholder="Hồn Thạch" style="width:60px"></div>';
    h+='<div class="pd" style="font-size:10px">Thư chỉ gửi chữ — không gửi được đồ hay vàng giữa người chơi.</div><button class="gbtn" id="mSend">Gửi thư</button></div>'; }
  b.innerHTML=h;
  b.querySelectorAll('[data-mt]').forEach(function(x){ x.onclick=function(){ MAIL.tab=x.getAttribute('data-mt'); renderMail(); }; });
  b.querySelectorAll('.mrow').forEach(function(x){ x.onclick=function(){ var id=+x.getAttribute('data-id'); MAIL.sel=MAIL.sel===id?null:id; var m=MAIL.list.filter(function(q){return q.id===id;})[0]; if(m&&!m.r){ m.r=1; ws.send(JSON.stringify({t:'mailread',mid:id})); } renderMail(); }; });
  b.querySelectorAll('[data-claim]').forEach(function(x){ x.onclick=function(e){ e.stopPropagation(); ws.send(JSON.stringify({t:'mailclaim',mid:+x.getAttribute('data-claim')})); }; });
  b.querySelectorAll('[data-del]').forEach(function(x){ x.onclick=function(e){ e.stopPropagation(); var id=+x.getAttribute('data-del'); gAsk('Xóa thư này?',function(){ ws.send(JSON.stringify({t:'maildel',mid:id})); }); }; });
  b.querySelectorAll('[data-rep]').forEach(function(x){ x.onclick=function(e){ e.stopPropagation(); MAIL.to=x.getAttribute('data-rep'); MAIL.tab='new'; renderMail(); }; });
  var sd=document.getElementById('mSend'); if(sd) sd.onclick=function(){ var o={t:'mailsend',to:document.getElementById('mTo').value,title:document.getElementById('mTi').value,body:document.getElementById('mBo').value};
    if(ADM.on){ var all=document.getElementById('mAll'); o.all=all&&all.checked?1:0; var at={}, g=+document.getElementById('mGold').value||0; if(g) at.gold=g; var mt={}; [['chaos','mChaos'],['bless','mBless'],['soul','mSoul']].forEach(function(q){ var v=+document.getElementById(q[1]).value||0; if(v) mt[q[0]]=v; }); if(Object.keys(mt).length) at.mats=mt; if(Object.keys(at).length) o.att=at; }
    if(o.all) gAsk('Gửi thư hệ thống cho TẤT CẢ nhân vật?',function(){ ws.send(JSON.stringify(o)); }); else ws.send(JSON.stringify(o)); MAIL.to=''; }; }
function mailAttTxt(a){ var L=[]; if(a.gold) L.push(a.gold+'🪙'); if(a.stones) L.push(a.stones+' đá cường'); if(a.mats) for(var k in a.mats) L.push(a.mats[k]+' '+(MATN[k]||k)); if(a.pots) for(var k2 in a.pots) L.push(a.pots[k2]+' bình '+k2); return L.join(', '); }
function mailBadge(n){ MAIL.n=n; var d=document.getElementById('maildot'); if(d) d.style.display=n>0?'block':'none'; var tg=document.getElementById('menuToggle'); if(tg) tg.classList.toggle('hasmail',n>0); }
