  o.innerHTML='<div class="gdbox"><div class="gdmsg"></div><div class="gdbtn" style="flex-wrap:wrap;justify-content:center"></div><div class="gdbtn" style="margin-top:8px"><button class="gbtn gdno">Huỷ</button></div></div>'; o.querySelector('.gdmsg').textContent=msg;
  var row=o.querySelectorAll('.gdbtn')[0]; opts.forEach(function(q){ var b=document.createElement('button'); b.className='gbtn'; b.textContent=q[1]; b.onclick=function(e){ e.preventDefault(); o.style.display='none'; setTimeout(function(){ cb(q[0]); },30); }; row.appendChild(b); });
