  document.getElementById('chBtn').addEventListener('pointerdown',function(e){ e.preventDefault(); e.stopPropagation(); CHAT.open=!CHAT.open; CHAT.unread=0; renderChatHud(); if(CHAT.open) setTimeout(function(){ try{ document.getElementById('chIn').focus(); }catch(_f){} },60); });
  document.getElementById('chMin').addEventListener('click',function(e){ e.preventDefault(); CHAT.open=false; renderChatHud(); });
  document.querySelectorAll('#chTabs button[data-t]').forEach(function(b){ b.addEventListener('click',function(){ CHAT.tab=b.getAttribute('data-t'); if(CHAT.tab==='guild'||CHAT.tab==='party') CHAT.ch=CHAT.tab; else if(CHAT.tab==='world') CHAT.ch='world'; renderChatHud(); }); });
