  const pool=MOB_TYPES[zone]||MOB_TYPES.forest; const mt=(camp&&pool.find(q=>q.id===camp.mt))||pool[Math.floor(Math.random()*pool.length)];
  const el=(tier>=2&&Math.random()<((z.floor||1)>=2?0.09:0.05)); // TINH ANH: hiếm, mạnh, rơi đồ tốt
