    dmg:Math.round(6*Math.pow(tier,1.05)*mt.dmgMul*(el?1.6:1)),mtype:mt.id,mname:(el?'⚜ ':'')+mt.name+(el?' Tinh Anh':''),mhue:mt.hue,mshape:mt.shape,rng:(RANGED[(mt.shape||'').replace('h:','')]?1:undefined),elite:el||undefined,
