function bossAoe(e,R,dmg,hue,slow){ fxEv('bimp',e.x,e.y,hue,1,bossEl(e),R);
  for(const pid in players){ const p=players[pid]; if(!p.chosen||p.dead||p.zone!==e.zone)continue; if(Math.hypot(p.x-e.x,p.y-e.y)<=R){ hurtPlayer(p,dmg,null,e); if(slow){ p.slowT=2; p.slowMul=0.5; } } }
  for(const pid in players){ const m=players[pid].merc; if(m&&m.zone===e.zone&&Math.hypot(m.x-e.x,m.y-e.y)<=R) mercHurt(m,dmg); } }
// ==== v3.29 BOSS KIỂU ELDEN RING: đòn có VÙNG BÁO TRƯỚC (né được), nổi điên ở 50% máu, thưởng cho mọi người góp sức
const HAZ=[];
