const BOSS_EL_BK={'h:b_dragonkin':4,'h:b_lavak':4,'h:b_icequeen':6,'h:b_butcher':2,'h:b_maw':3,'h:b_psycho':3,'h:b_taur':0,lava:4,jelly:6,daddy:2,maw:3,psycho:3,taur:0,'h:b_minoking':0,'h:b_skelking':3,'h:b_archangel':5};
