// ===== v3.41 BẢN SẮC LỐI CHƠI (kiểu LMHT): hất tung · đấu trường · lốc kiếm · tuyệt kỹ trên không · tên bạc =====
// ================= v3.43 PK · THÁCH ĐẤU · KHO ĐỒ · KỸ NĂNG SÓI THẦN =================
const PK_MURDER=25, PK_OUTLAW=60;      // 1 mạng = 25 điểm · ≥60 (3 mạng) = TRUY NÃ
function isOutlaw(p){ return (p.pkScore||0)>=PK_OUTLAW; }
function pidOf(o){ for(const k in players) if(players[k]===o) return +k; return null; }
function idOf(o){ return pidOf(o); }
function duelPair(a,b){ return a.duel&&a.duel===b.duel&&DUELS[a.duel]&&DUELS[a.duel].live; }
function canPvp(a,o){ if(a===o) return false; if(duelPair(a,o)) return true; if(a.duel||o.duel) return false;
  const z=ZONES[o.zone]; if(!z||z.safe||z.arena) return false; if(isOutlaw(o)) return true; if(a.pkOn) return true;
  const ai=pidOf(a); if(ai!=null&&o._aggr&&o._aggr[ai]&&Date.now()-o._aggr[ai]<30000) return true;   // tự vệ
  return false; }
function outlawBlock(p,id){ if(isOutlaw(p)){ sendTo(id,{t:'toast',text:'⛔ Đang bị TRUY NÃ — không ai buôn bán, giữ đồ hay dịch chuyển cho ngươi.'}); return true; } return false; }
// ---- Thách đấu: 10 mạng thắng trước, đầu hàng, rời mạng = thua ----
const DUELS={}; let nextDuel=1; const DUEL_WIN=10;
function startDuel(a,ai,b,bi){ if(a.duel||b.duel||a.dead||b.dead) return; const id=nextDuel++;
  const D={id,a:ai,b:bi,sa:0,sb:0,live:true,t0:Date.now(),ret:{[ai]:{z:a.zone,x:a.x,y:a.y},[bi]:{z:b.zone,x:b.x,y:b.y}}}; DUELS[id]=D; a.duel=b.duel=id;
  if(a.mounted) doToggleMount(a,ai,a.mounted); if(b.mounted) doToggleMount(b,bi,b.mounted); duelPlace(D,true);
  bcast({t:'toast',text:'⚔️ '+(a.charDisplayName||'#'+ai)+' và '+(b.charDisplayName||'#'+bi)+' bước vào Đấu Trường Sinh Tử!'}); duelSend(D,'Bắt đầu sau 3 giây'); }
function duelPlace(D,first){ const a=players[D.a], b=players[D.b]; if(!a||!b) return; const k=(D.id%4), cy=230+k*90;
  for(const [p,x] of [[a,390],[b,610]]){ p.zone='arena'; p.x=x; p.y=cy; p._wz=null; p.dead=false; p.hp=p.maxhp; p.mp=p.maxmp; p.iframe=first?3:1.5; p.slowT=0; }
  a.fx=1; a.fy=0; b.fx=-1; b.fy=0; CURZ='arena'; fxEv('warpin',a.x,a.y,0,0,0,40); fxEv('warpin',b.x,b.y,0,0,0,40); }
function duelSend(D,note){ const a=players[D.a], b=players[D.b]; const m={t:'duel',on:D.live?1:0,a:D.a,b:D.b,na:a?(a.charDisplayName||'#'+D.a):'?',nb:b?(b.charDisplayName||'#'+D.b):'?',sa:D.sa,sb:D.sb,win:DUEL_WIN,note:note||''};
  sendTo(D.a,m); sendTo(D.b,m); }
function duelDeath(o,atkPid){ const D=DUELS[o.duel]; if(!D||!D.live) return false; const oi=pidOf(o); if(atkPid==null||(atkPid!=D.a&&atkPid!=D.b)) { o.hp=1; return true; }
  if(oi===D.a) D.sb++; else D.sa++;
  if(D.sa>=DUEL_WIN||D.sb>=DUEL_WIN){ endDuel(D,D.sa>D.sb?D.a:D.b,'thắng tuyệt đối'); return true; }
  duelPlace(D,false); duelSend(D,(oi===D.a?'#'+D.b:'#'+D.a)+' ghi điểm'); return true; }
function endDuel(D,winId,why){ if(!D.live) return; D.live=false; const loseId=winId===D.a?D.b:D.a; const w=players[winId], l=players[loseId];
  for(const pid of [D.a,D.b]){ const p=players[pid]; if(!p) continue; const r=D.ret[pid]; p.duel=null; p.dead=false; p.hp=p.maxhp; p.mp=p.maxmp; p.iframe=2;
    const back=(r&&ZONES[r.z]&&!ZONES[r.z].arena)?r:{z:'town',x:450,y:350}; p.zone=back.z; p.x=back.x; p.y=back.y; p._wz=null; }
  const nm=x=>x?(x.charDisplayName||'#'+pidOf(x)):'?';
  duelSend(D,'Kết thúc'); bcast({t:'toast',text:'🏆 '+nm(w)+' đánh bại '+nm(l)+' '+Math.max(D.sa,D.sb)+'–'+Math.min(D.sa,D.sb)+' ('+why+')'});
  if(w){ w.duelW=(w.duelW||0)+1; } if(l){ l.duelL=(l.duelL||0)+1; } delete DUELS[D.id]; }
function duelQuit(p,id){ const D=DUELS[p.duel]; if(!D) return; endDuel(D,id==D.a?D.b:D.a,'đối thủ đầu hàng'); }
setInterval(()=>{ const now=Date.now(); for(const k in DUELS){ const D=DUELS[k]; if(!players[D.a]) endDuel(D,D.b,'đối thủ bỏ chạy'); else if(!players[D.b]) endDuel(D,D.a,'đối thủ bỏ chạy');
  else if(now-D.t0>12*60000) endDuel(D,D.sa>=D.sb?D.a:D.b,'hết giờ'); } },1000);
// ---- lời mời chung: tổ đội / thách đấu / hội ----
function doDuelReq(p,id,tid){ const t=players[tid]; if(!t||!t.chosen||tid==id) return; if(p.duel||t.duel){ sendTo(id,{t:'toast',text:'Một bên đang trong trận thách đấu.'}); return; }
  if(isOutlaw(p)){ sendTo(id,{t:'toast',text:'Kẻ bị truy nã không được thách đấu.'}); return; }
  t.pendDuel={from:id,t:Date.now()}; sendTo(tid,{t:'inviteReceived',fromId:id,kind:'duel',text:(p.charDisplayName||'#'+id)+' (Lv '+p.lv+') thách đấu ngươi — 10 mạng thắng trước'}); sendTo(id,{t:'toast',text:'Đã gửi lời thách đấu.'}); }
function doGuildInv(p,id,tid){ const g=guildOf(id), t=players[tid]; if(!g||!t||t.guild) return; if(!(g.leader===id||g.officers.includes(id))){ sendTo(id,{t:'toast',text:'Chỉ chủ hội / phó hội mới mời được.'}); return; }
  t.pendGuild={gid:g.id,t:Date.now()}; sendTo(tid,{t:'inviteReceived',fromId:id,kind:'guild',text:(p.charDisplayName||'#'+id)+' mời ngươi vào hội '+g.name}); sendTo(id,{t:'toast',text:'Đã gửi lời mời vào hội.'}); }
function doAcceptKind(p,id,kind){
  if(kind==='duel'){ const q=p.pendDuel; p.pendDuel=null; if(!q||Date.now()-q.t>30000) return; const a=players[q.from]; if(!a) return; startDuel(a,+q.from,p,+id); return; }
  if(kind==='guild'){ const q=p.pendGuild; p.pendGuild=null; if(!q||p.guild) return; const g=guilds[q.gid]; if(!g||g.members.length>=30) return; g.members.push(id); p.guild=g.id; broadcastGuild(g.id); return; }
  doAcceptInvite(p,id); }
// ---- KHO ĐỒ (NPC Thủ Kho): cất miễn phí, lấy ra mất phí nhỏ ----
const VAULT_MAX=48;
function vaultFee(it){ return Math.max(10,Math.round(sellValue(it)*0.15)); }
function nearKind(p,kind){ return NPCS.some(n=>n.kind===kind&&n.zone===p.zone&&Math.hypot(p.x-n.x,p.y-n.y)<170); }
function sendVault(p,id){ p.vault=p.vault||[]; p.vault.forEach(ensureLook); sendTo(id,{t:'vault',items:p.vault,fees:p.vault.map(vaultFee),max:VAULT_MAX}); }
function doVaultPut(p,id,itemId){ if(!nearKind(p,'vault')||outlawBlock(p,id)) return; p.vault=p.vault||[]; if(p.vault.length>=VAULT_MAX){ sendTo(id,{t:'toast',text:'Kho đầy.'}); return; }
  const i=p.inv.findIndex(x=>x.id===itemId); if(i<0) return; p.vault.push(p.inv.splice(i,1)[0]); sendInv(p,id); sendVault(p,id); }
function doVaultTake(p,id,itemId){ if(!nearKind(p,'vault')||outlawBlock(p,id)) return; p.vault=p.vault||[]; const i=p.vault.findIndex(x=>x.id===itemId); if(i<0) return;
  if(p.inv.length>=24){ sendTo(id,{t:'toast',text:'Túi đầy.'}); return; } const fee=vaultFee(p.vault[i]); if(p.gold<fee){ sendTo(id,{t:'toast',text:'Cần '+fee+'🪙 phí lấy đồ.'}); return; }
  p.gold-=fee; p.inv.push(p.vault.splice(i,1)[0]); sendInv(p,id); sendVault(p,id); }
// ---- KỸ NĂNG SÓI THẦN (kiểu Sói Tinh MU) ----
const MSKILL={frostwolf:{n:'Bão Tuyết Băng Nguyên',cd:14},shadowwolf:{n:'Hư Không Lôi Bạo',cd:12},direwolf:{n:'Lang Vương Hống',cd:16}};
function doMountSkill(p,id){ const M=MSKILL[p.mounted]; if(!M||p.dead) return; const now=Date.now(); if((p._mskT||0)>now) return; p._mskT=now+M.cd*1000; CURZ=p.zone; setPose(p,'roar',0.7); fxEx({kind:'g',s:'mroar',id:+id,x:Math.round(p.x),y:Math.round(p.y),mt:p.mounted});
  const base=POW(p)*1.9+(p.lv||1)*9, hits=[];
  const foes=[]; for(const eid in enemies){ const e=enemies[eid]; if(!e.dead&&e.zone===p.zone) foes.push(e); }
  const pfoes=[]; for(const k in players){ const o=players[k]; if(o!==p&&o.chosen&&!o.dead&&o.zone===p.zone&&canPvp(p,o)) pfoes.push(o); }
  if(p.mounted==='frostwolf'){ const R=200; foes.forEach(e=>{ if(Math.hypot(e.x-p.x,e.y-p.y)<R){ hurtEnemy(e,base*1.1,id); e.slowT=e.boss?0.6:1.6; e.slowMul=0.02; } });
    pfoes.forEach(o=>{ if(Math.hypot(o.x-p.x,o.y-p.y)<R){ hurtPlayer(o,base*0.9,id); o.slowT=1.2; o.slowMul=0.05; } }); fxEx({kind:'mfrost',x:Math.round(p.x),y:Math.round(p.y),R}); }
  else if(p.mounted==='shadowwolf'){ let cur={x:p.x,y:p.y}; const used=new Set(); const pts=[[Math.round(p.x),Math.round(p.y-20)]];
    for(let k=0;k<6;k++){ let best=null,bd=280; for(const e of foes.concat(pfoes)){ if(used.has(e))continue; const d=Math.hypot(e.x-cur.x,e.y-cur.y); if(d<bd){bd=d;best=e;} } if(!best)break; used.add(best);
      if(foes.includes(best)) hurtEnemy(best,base*(1-k*0.08),id); else hurtPlayer(best,base*0.8*(1-k*0.08),id); pts.push([Math.round(best.x),Math.round(best.y-20)]); cur=best; }
    fxEx({kind:'mchain',pts}); }
  else if(p.mounted==='direwolf'){ const R=230; foes.forEach(e=>{ if(Math.hypot(e.x-p.x,e.y-p.y)<R){ hurtEnemy(e,base,id); knockUp(e,1.0); } });
    pfoes.forEach(o=>{ if(Math.hypot(o.x-p.x,o.y-p.y)<R) hurtPlayer(o,base*0.8,id); }); p._howlU=now+6000; fxEx({kind:'mhowl',x:Math.round(p.x),y:Math.round(p.y),R}); }
  sendTo(id,{t:'mskill',cd:M.cd}); }
// kỹ năng không dùng được khi cưỡi (nhào lộn / xoay / bay chém) — phải xuống thú
const MBLOCK=new Set(['mirrorstep','twinshot','voidsword','swordwave','iceblade','elemshift','dualresonance']);
const CAGES=[];
// đòn nặng phải gồng/vận công trước khi tung (cảm giác có lực)
const TEL_SKIP=new Set(['dash','predstep','mirrorstep','wcounter','laststand','bodyward','windguard','shield','allybuff','spiritheal','buff','elemshift','tacticalrecall','huntmark','ravenmark','soulledger']);
// hình báo trước (người khác thấy để né): đường thẳng / quạt / vòng tròn theo thông số kỹ năng
function telShape(p,sk){ const fx=p.fx||1, fy=p.fy||0, a=Math.atan2(fy,fx), r1=v=>Math.round(v);
  if(sk.g&&sk.radius&&sk.range&&typeof gAimPt==='function'){ const q=gAimPt(p,sk.range); return {sh:'c',x:r1(q[0]),y:r1(q[1]),R:sk.radius}; }
  if(sk.len&&sk.width) return {sh:'line',x:r1(p.x),y:r1(p.y),x2:r1(p.x+fx*sk.len),y2:r1(p.y+fy*sk.len),w:sk.width};
  if(sk.arc) { const R=sk.rangeOut||sk.range||130; return {sh:'cone',x:r1(p.x),y:r1(p.y),a:+a.toFixed(2),arc:Math.min(3.1,sk.arc*2),R}; }
  if(sk.speed){ const L=Math.min(520,sk.range||sk.throwRange||420); return {sh:'line',x:r1(p.x),y:r1(p.y),x2:r1(p.x+fx*L),y2:r1(p.y+fy*L),w:(sk.r||8)*3}; }
  if(sk.radius){ const far=(sk.range&&p.wasAimed)?sk.range*(p.aimMag||1):0; return {sh:'c',x:r1(p.x+fx*far),y:r1(p.y+fy*far),R:sk.radius}; }
  if(sk.range||sk.dist||sk.dashDist){ const L=sk.range||sk.dist||sk.dashDist; return {sh:'line',x:r1(p.x),y:r1(p.y),x2:r1(p.x+fx*L),y2:r1(p.y+fy*L),w:40}; }
  return {sh:'c',x:r1(p.x),y:r1(p.y),R:90}; }
