function airNear(p){ for(const eid in enemies){ const e=enemies[eid]; if(!e.dead&&e.zone===p.zone&&e.airT>0&&Math.hypot(e.x-p.x,e.y-p.y)<450) return true; } return false; }
function knockUp(e,dur){ if(!e||e.dead)return; if(e.boss) dur=Math.min(dur,0.35); else dur=Math.max(dur,1.0); e.airT=Math.max(e.airT||0,dur); e.airD=Math.max(e.airD||0,dur); e.dashT=0; }
function enemiesNearSeg(p,x0,y0,x1,y1,w){ const out=[]; const vx=x1-x0, vy=y1-y0, L=vx*vx+vy*vy||1;
  for(const eid in enemies){ const e=enemies[eid]; if(e.dead||e.zone!==p.zone)continue; const t=Math.max(0,Math.min(1,((e.x-x0)*vx+(e.y-y0)*vy)/L));
    if(Math.hypot(e.x-(x0+vx*t),e.y-(y0+vy*t))<=w/2+(e.r||14)) out.push(e); } return out; }
function makeCage(p,id,x,y,r,dur){ const now=Date.now(); const c={x,y,r,zone:p.zone,until:now+dur*1000,owner:+id,ids:[]};
  for(const eid in enemies){ const e=enemies[eid]; if(!e.dead&&e.zone===p.zone&&Math.hypot(e.x-x,e.y-y)<r){ c.ids.push(eid); e.cageU=c.until; } }
  CAGES.push(c); p._arenaU=c.until; CURZ=p.zone; fxEx({kind:'cage',x:Math.round(x),y:Math.round(y),R:r,dur}); }
function tickCages(){ const now=Date.now(); for(let i=CAGES.length-1;i>=0;i--){ const c=CAGES[i]; if(now>c.until){ CAGES.splice(i,1); continue; }
  for(const eid of c.ids){ const e=enemies[eid]; if(!e||e.dead)continue; const dx=e.x-c.x, dy=e.y-c.y, d=Math.hypot(dx,dy); const lim=c.r-12; if(d>lim){ e.x=c.x+dx/d*lim; e.y=c.y+dy/d*lim; } } } }
setInterval(tickCages,50);
