function setPose(p,k,d){ p.poseK=k; p.poseT=d; p.poseD=d; }
// ================= v3.49 HỆ KỸ NĂNG MỚI: cây cha–con, 3 nhánh/class, nội tại, ~30 chiêu mới =================
// Cảm hứng: Liên Minh / Liên Quân (móc kéo, đẩy vào tường, tường gió, ấn tử thần, bom thời gian, đại băng tiễn...) — tên & cơ chế làm lại cho hợp game.
const GSK_VER=49;
const WWALLS=[]; const GDAG=[]; const GPEND=[];
function gNow(){ return Date.now(); }
function gR(v){ return Math.round(v); }
function gFoes(p,id,test){ const out=[];
  for(const eid in enemies){ const e=enemies[eid]; if(e.dead||e.zone!==p.zone) continue; if(test(e)) out.push({ent:e,e:1,id:eid}); }
  for(const k in players){ if(+k===+id) continue; const o=players[k]; if(!o.chosen||o.dead||o.iframe>0||o.zone!==p.zone||zoneOf(o).safe) continue; if(!canPvp(p,o)) continue; if(test(o)) out.push({ent:o,e:0,id:+k}); }
  return out; }
function gInCircle(x,y,R){ return t=>Math.hypot(t.x-x,t.y-y)<=R+(t.r||12)*0.5; }
function gInSeg(x0,y0,x1,y1,w){ const vx=x1-x0, vy=y1-y0, L=vx*vx+vy*vy||1; return t=>{ const u=Math.max(0,Math.min(1,((t.x-x0)*vx+(t.y-y0)*vy)/L)); return Math.hypot(t.x-(x0+vx*u),t.y-(y0+vy*u))<=w/2+(t.r||12)*0.5; }; }
function gInCone(x,y,a,R,arc){ return t=>{ const dx=t.x-x, dy=t.y-y, d=Math.hypot(dx,dy); if(d>R+(t.r||12)*0.5) return false; if(d<14) return true; let df=Math.abs(Math.atan2(dy,dx)-a); if(df>Math.PI) df=2*Math.PI-df; return df<=arc; }; }
function gFirstOnSeg(p,id,x0,y0,x1,y1,w){ const L=gFoes(p,id,gInSeg(x0,y0,x1,y1,w)); let best=null, bd=1e9; L.forEach(f=>{ const d=Math.hypot(f.ent.x-x0,f.ent.y-y0); if(d<bd){ bd=d; best=f; } }); return best; }
function gNearest(p,id,R,test){ let best=null, bd=R; gFoes(p,id,t=>true).forEach(f=>{ if(test&&!test(f.ent)) return; const d=Math.hypot(f.ent.x-p.x,f.ent.y-p.y); if(d<bd){ bd=d; best=f; } }); return best; }
function gD(p,sk,rank,k,base){ return ((base!=null?base:(sk.dmg||0))+POW(p)*(k==null?1:k))*rankMul(rank||1); }
function gHit(p,id,f,dmg,opt){ if(!f||!f.ent||f.ent.dead) return; opt=opt||{}; const d=applyPassiveOnHit(p,id,f.ent,dmg)*markBonus(f.ent);
  if(f.e) hurtEnemy(f.ent,d,id); else hurtPlayer(f.ent,d*PVP,id); }
function gStun(f,dur,frz){ const t=f.ent; if(!t||t.dead) return; if(f.e){ if(t.boss) dur=Math.min(dur,0.4); t.stunT=Math.max(t.stunT||0,dur); t.windT=null; if(frz) t.frzT=Math.max(t.frzT||0,dur); }
  else { dur*=0.7; t.stunT=Math.max(t.stunT||0,dur); if(frz) t.frzT=Math.max(t.frzT||0,dur); } pvOnCC(f); }
function gSlow(f,mul,dur){ const t=f.ent; if(!t||t.dead) return; t.slowT=Math.max(t.slowT||0,dur); t.slowMul=Math.min((t.slowT>0&&t.slowMul)||1,mul); }
function gKup(f,dur){ const t=f.ent; if(!t||t.dead) return; if(f.e) knockUp(t,dur); else { t.stunT=Math.max(t.stunT||0,Math.min(dur,1.0)*0.7); setPose(t,'air',Math.min(dur,1.0)); } pvOnCC(f); }
function gMove(t,x,y){ const ox=t.x, oy=t.y; t.x=x; t.y=y; if(t.dashT!==undefined||t.maxhp&&!t.chosen) clampEnemyPos(t); else clampPos(t); if(wallAt(t.zone,t.x,t.y)){ t.x=ox; t.y=oy; return false; } return true; }
// đẩy theo hướng; trả về true nếu va tường
function gPush(f,ax,ay,dist){ const t=f.ent; if(!t||t.dead||(f.e&&t.boss)) return false; const d=Math.hypot(ax,ay)||1, ux=ax/d, uy=ay/d; let moved=0, hit=false;
  for(let s=0;s<dist;s+=12){ const nx=t.x+ux*12, ny=t.y+uy*12; const Z=ZONES[t.zone]||{}; if(wallAt(t.zone,nx,ny)||nx<20||ny<20||nx>(Z.w||9999)-20||ny>(Z.h||9999)-20){ hit=true; break; } t.x=nx; t.y=ny; moved+=12; }
  return hit; }
function gPull(f,tx,ty,keep){ const t=f.ent; if(!t||t.dead||(f.e&&t.boss)) return; const dx=tx-t.x, dy=ty-t.y, d=Math.hypot(dx,dy); if(d<=keep) return; const go=d-keep; const ux=dx/d, uy=dy/d;
  for(let s=0;s<go;s+=12){ const nx=t.x+ux*Math.min(12,go-s), ny=t.y+uy*Math.min(12,go-s); if(wallAt(t.zone,nx,ny)) break; t.x=nx; t.y=ny; } }
function gFx(p,o){ CURZ=p.zone; fxEx(Object.assign({kind:'g'},o)); }
function gAimPt(p,R){ if(p.wasAimed){ const r=R*(p.aimMag||1); return [p.x+p.fx*r, p.y+p.fy*r]; } const n=gNearest(p,pidOf(p),R); if(n) return [n.ent.x,n.ent.y]; return [p.x+p.fx*R*0.6, p.y+p.fy*R*0.6]; }
function gAutoFace(p,id,R){ if(p.wasAimed) return; const n=gNearest(p,id,R); if(n){ const a=Math.atan2(n.ent.y-p.y,n.ent.x-p.x); p.fx=Math.cos(a); p.fy=Math.sin(a); } }
function gLater(ms,fn){ GPEND.push({at:gNow()+ms,fn}); }
setInterval(()=>{ const now=gNow(); for(let i=GPEND.length-1;i>=0;i--){ const q=GPEND[i]; if(q.at>now) continue; GPEND.splice(i,1); try{ q.fn(); }catch(e){ console.error('gsk later',e&&e.message); } } },25);
