function pvR(p,pid){ const q=PASMAP[pid]; if(!q||q.cls!==p.cls) return 0; if(q.root) return 1; return Math.min(3,(p.skRank&&p.skRank[pid])||0); }
function pvV(p,pid,arr){ const r=pvR(p,pid); return r?arr[r-1]:0; }

// ---------- CÂY KỸ NĂNG (cha → con) ----------
// Mỗi nhánh: [Nội tại 1] → (chiêu a1, chiêu a2) ; a1 → a3 ; a2 → [Nội tại 2] → TUYỆT KỸ
const TREE2={
 war:{core:[['wp0'],['w1','w2'],['w11','w3','w4'],['wpc']], par:{w3:'w2',w4:'w2',w11:'w1',wpc:'w3'},
      br:[['wpA1','w6','w8','w7','wpA2','w10'],['wpB1','w5','w9','w14','wpB2','w15'],['wpC1','w16','w19','w17','wpC2','w18']]},
 mage:{core:[['mp0'],['m1','m2'],['m13','m3','m4'],['mpc']], par:{m3:'m2',m4:'m2',m13:'m1',mpc:'m3'},
      br:[['mpA1','m10','m14','m12','mpA2','m5'],['mpB1','m8','m7','m6','mpB2','m15'],['mpC1','m16','m11','m9','mpC2','m17']]},
 arc:{core:[['ap0'],['a1','a2'],['a4','a3','a11'],['apc']], par:{a3:'a2',a4:'a1',a11:'a2',apc:'a3'},
      br:[['apA1','a8','a5','a13','apA2','a12'],['apB1','a6','a9','a7','apB2','a10'],['apC1','a14','a16','a17','apC2','a15']]},
 blade:{core:[['bp0'],['b1','b2'],['b11','b3','b7'],['bpc']], par:{b3:'b2',b7:'b2',b11:'b1',bpc:'b3'},
      br:[['bpA1','b8','b9','b12','bpA2','b4'],['bpB1','b5','b6','b13','bpB2','b10'],['bpC1','b14','b15','b17','bpC2','b16']]},
 cmd:{core:[['cp0'],['c1','c2','c4'],['c14','c3','c12'],['cpc']], par:{c3:'c2',c12:'c4',c14:'c1',cpc:'c12'},
      br:[['cpA1','c5','c7','c11','cpA2','c13'],['cpB1','c8','c9','c6','cpB2','c10'],['cpC1','c15','c16','c18','cpC2','c17']]}
};
const TPAR={}, TBR={}, TROW={}; // cha, nhánh, hàng
function gTreeInit(){ for(const c in TREE2){ const T=TREE2[c]; T.core.forEach((row,ri)=>row.forEach(id=>{ TBR[id]=-1; TROW[id]=ri; if(T.par[id]) TPAR[id]=T.par[id]; }));
  T.br.forEach((L,bi)=>{ const [P1,a1,a2,a3,P2,U]=L; [P1,a1,a2,a3,P2,U].forEach(id=>TBR[id]=bi); TPAR[a1]=P1; TPAR[a2]=P1; TPAR[a3]=a1; TPAR[P2]=a2; TPAR[U]=P2;
    TROW[P1]=0; TROW[a1]=1; TROW[a2]=1; TROW[a3]=2; TROW[P2]=2; TROW[U]=3;
    // cấp mở khóa theo độ sâu
    const LVS={[P1]:40,[a1]:45,[a2]:55,[a3]:75,[P2]:90,[U]:110};
    for(const id in LVS){ const sk=(SKILLS[c]||[]).find(x=>x.id===id); if(sk) sk.unlockLv=LVS[id]; const q=PASMAP[id]; if(q) q.lv=LVS[id]; } }); } }
function nodeLearned(p,id){ const q=PASMAP[id]; if(q) return pvR(p,id)>0; return ((p.skRank&&p.skRank[id])||1)>=2; }
function parentOK(p,id){ const par=TPAR[id]; if(!par) return true; return nodeLearned(p,par); }

