const NODES={}; let nextNode=1; const NODE_N=12, PROF_MAX=50;
function profNeed(lv){ return 60+lv*45; }
function profOf(p,k){ p.prof=p.prof||{}; return p.prof[k]=p.prof[k]||{lv:1,xp:0}; }
function profXP(p,id,k,x){ const P=profOf(p,k); if(P.lv>=PROF_MAX) return; P.xp+=x; let up=false; while(P.xp>=profNeed(P.lv)&&P.lv<PROF_MAX){ P.xp-=profNeed(P.lv); P.lv++; up=true; }
  if(up) sendTo(id,{t:'toast',text:'⬆ '+({mine:'Khai Khoáng',herb:'Hái Thuốc',craft:'Luyện Chế'}[k])+' đạt cấp '+P.lv}); }
function nodeTier(z){ const t=ztier(z); return t<=4?1:(t<=9?2:3); }
function spawnNodes(z){ const Z=ZONES[z]; if(!Z||Z.safe||Z.arena) return; NODES[z]=NODES[z]||[]; const L=NODES[z]; let tries=0;
  while(L.length<NODE_N&&tries++<400){ const x=80+Math.random()*(Z.w-160), y=80+Math.random()*(Z.h-160); if(wallAt(z,x,y)||wallAt(z,x+20,y)||wallAt(z,x-20,y)) continue;
    if((Z.portals||[]).some(q=>Math.hypot(q.x-x,q.y-y)<160)) continue; if(L.some(n=>Math.hypot(n.x-x,n.y-y)<120)) continue;
    L.push({id:nextNode++,x:Math.round(x),y:Math.round(y),k:(L.length%2?'herb':'ore'),t:nodeTier(z),uses:3,on:true,back:0}); } }
function nodesMsg(z){ return {t:'nodes',zone:z,list:(NODES[z]||[]).filter(n=>n.on).map(n=>[n.id,n.x,n.y,n.k,n.t])}; }
function nodesBcast(z){ const m=nodesMsg(z); for(const k in players){ const p=players[k]; if(p.chosen&&p.zone===z) sendTo(+k,m); } }
setTimeout(()=>{ COMBAT_ZONES.forEach(spawnNodes); },3000);
setInterval(()=>{ const now=Date.now(); for(const z in NODES){ let ch=false; NODES[z].forEach(n=>{ if(!n.on&&now>n.back){ n.on=true; n.uses=3; ch=true; } }); if(ch) nodesBcast(z); }
  for(const k in players){ const p=players[k]; if(!p.chosen) continue; if(p._nz!==p.zone){ p._nz=p.zone; sendTo(+k,nodesMsg(p.zone)); }
    const g=p.gather; if(g){ if(p.dead||p.zone!==g.z||Math.hypot(p.x-g.x,p.y-g.y)>14){ p.gather=null; sendTo(+k,{t:'gather',dur:0}); } else if(now>=g.end){ p.gather=null; finishGather(p,+k,g); } } } },200);
function doGather(p,id,nid){ if(p.dead||p.mounted||p.gather) return; const L=NODES[p.zone]||[]; let n=null;
  if(nid!=null) n=L.find(q=>q.id===+nid&&q.on); else { let bd=80; L.forEach(q=>{ if(!q.on) return; const d=Math.hypot(q.x-p.x,q.y-p.y); if(d<bd){ bd=d; n=q; } }); }
  if(!n){ if(nid!=null) sendTo(id,{t:'toast',text:'Lại gần hơn.'}); return false; } if(Math.hypot(n.x-p.x,n.y-p.y)>80){ sendTo(id,{t:'toast',text:'Lại gần hơn.'}); return false; }
  const P=profOf(p,n.k==='ore'?'mine':'herb'); const dur=Math.max(0.9,2.0-P.lv*0.02);
  p.gather={nid:n.id,z:p.zone,x:p.x,y:p.y,end:Date.now()+dur*1000}; setPose(p,'crouch',dur); sendTo(id,{t:'gather',dur,k:n.k}); return true; }
function finishGather(p,id,g){ const L=NODES[g.z]||[]; const n=L.find(q=>q.id===g.nid&&q.on); if(!n) return; const pk=n.k==='ore'?'mine':'herb', P=profOf(p,pk);
  const key=(n.k==='ore'?'ore':'herb')+n.t, cnt=1+Math.floor(Math.random()*2)+Math.floor(P.lv/12); p.mats=p.mats||{}; p.mats[key]=(p.mats[key]||0)+cnt;
  let bonus=''; const rare=0.06+P.lv*0.002; if(Math.random()<rare){ const st=5*n.t+Math.floor(Math.random()*6*n.t); p.stones=(p.stones||0)+st; bonus=' + '+st+' đá cường!'; }
  profXP(p,id,pk,8+n.t*6); n.uses--; if(n.uses<=0){ n.on=false; n.back=Date.now()+90000; nodesBcast(g.z); }
  CURZ=g.z; bcastZ({t:'loot',id,x:p.x,y:p.y,txt:'+'+cnt+' '+MATS[key].replace(/^\S+\s/,'')+bonus}); sendInv(p,id); }
