    if(e.fearT>0){ e.fearT-=dt; const fa=Math.atan2(e.y-e.fearY,e.x-e.fearX); const fs=(e.spd||70)*0.95*dt; e.x+=Math.cos(fa)*fs; e.y+=Math.sin(fa)*fs; clampEnemyPos(e); e.windT=null; continue; }
    let tp=null,tpIll=false,best=1e9;
