      if(e.aggroId&&e.aggroT>0){ const ap=players[e.aggroId]; if(ap&&ap.chosen&&!ap.dead&&ap.zone===e.zone){ tp=ap; tpIll=false; best=Math.hypot(ap.x-e.x,ap.y-e.y); } }
      const aggroR=(e.elite?200:(e.rover?150:165));
